/**
 * V2.8 AI Privacy, Scope Boundaries & Prompt Injection Defense Engine
 * Enforces pre-retrieval scope validation, sensitive domain exclusions,
 * anti-spoofing citation handles, proposal schema validation without eval,
 * and lock-interruption response discard.
 */

import { authorizationGatewayV2, ExecutionContextV2 } from './authorizationGatewayV2';
import { DomainSensitivityV2 } from './securityTypesV2';
import { vaultLockSessionManagerV2 } from './vaultLockSessionManagerV2';

export interface AIRequestContextV2 {
  requestId: string;
  provider: 'local_on_device' | 'external_cloud';
  providerName: string;
  sourceResourceIds: string[];
  userPrompt: string;
  explicitSensitiveDomainGrant?: boolean;
  scheduledSessionGeneration: number;
}

export interface GroundedSourceItemV2 {
  id: string;
  title: string;
  domain: string;
  sensitivity: DomainSensitivityV2;
  content: string;
  systemCitationHandle: string; // e.g. "SRC_7b2f_1"
}

export interface AIActionProposalV2 {
  actionId: string;
  actionType: 'create_note' | 'update_property' | 'append_text' | 'schedule_task';
  targetResourceId?: string;
  expectedResourceVersion?: number;
  payload: Record<string, any>;
  rationale?: string;
  requiresUserConfirmation: boolean;
}

export class AISecurityGuardV2 {
  private static instance: AISecurityGuardV2;

  private constructor() {}

  public static getInstance(): AISecurityGuardV2 {
    if (!AISecurityGuardV2.instance) {
      AISecurityGuardV2.instance = new AISecurityGuardV2();
    }
    return AISecurityGuardV2.instance;
  }

  /**
   * Filters and validates source resources before retrieval or dispatch to an AI provider.
   * Excludes Health & Finance by default unless explicit per-request user grant is provided.
   */
  public filterAndFrameSources(
    sources: Array<{ id: string; title: string; domain: string; content: string }>,
    options: {
      provider: 'local_on_device' | 'external_cloud';
      explicitSensitiveGrant?: boolean;
    }
  ): {
    permittedSources: GroundedSourceItemV2[];
    excludedSensitiveCount: number;
    framedPromptSources: string;
    citationMap: Map<string, string>; // systemCitationHandle -> resourceId
  } {
    const permittedSources: GroundedSourceItemV2[] = [];
    let excludedSensitiveCount = 0;
    const citationMap = new Map<string, string>();

    const nonce = Math.random().toString(36).slice(2, 6);
    let index = 1;

    for (const src of sources) {
      const sensitivity = authorizationGatewayV2.classifyDomainSensitivity(src.domain);

      // Default privacy rule: Highly sensitive domains (Finance, Health, Credentials) are excluded
      // from external cloud AI unless explicitly granted by user for this prompt
      if (
        sensitivity === 'highly_sensitive' &&
        options.provider === 'external_cloud' &&
        !options.explicitSensitiveGrant
      ) {
        excludedSensitiveCount += 1;
        continue;
      }

      const systemCitationHandle = `SRC_${nonce}_${index++}`;
      citationMap.set(systemCitationHandle, src.id);

      // Sanitize raw content to prevent citation spoofing (e.g. text containing [S1] or source tags)
      const sanitizedContent = this.sanitizeSourceTextForFraming(src.content, nonce);

      permittedSources.push({
        id: src.id,
        title: src.title,
        domain: src.domain,
        sensitivity,
        content: sanitizedContent,
        systemCitationHandle,
      });
    }

    // Build system-controlled source delimiters that an adversarial prompt cannot break out of
    const framedPromptSources = permittedSources
      .map(
        (s) =>
          `<<<UNTRUSTED_SOURCE_DOCUMENT handle="${s.systemCitationHandle}" title="${s.title}" domain="${s.domain}">>>\n${s.content}\n<<<END_UNTRUSTED_SOURCE_DOCUMENT handle="${s.systemCitationHandle}">>>`
      )
      .join('\n\n');

    return {
      permittedSources,
      excludedSensitiveCount,
      framedPromptSources,
      citationMap,
    };
  }

  /**
   * Prevents adversarial source content from manipulating citation mapping or injecting system directives.
   */
  private sanitizeSourceTextForFraming(rawContent: string, nonce: string): string {
    if (!rawContent) return '';
    let text = rawContent;
    // Disarm pseudo-citation spoofing and pseudo system framing tokens
    text = text.replace(/<<<UNTRUSTED_SOURCE_DOCUMENT/gi, '<<<ESCAPED_DOCUMENT');
    text = text.replace(/<<<END_UNTRUSTED_SOURCE_DOCUMENT/gi, '<<<END_ESCAPED_DOCUMENT');
    text = text.replace(/SYSTEM\s*:\s*/gi, '[Disarmed Directive]: ');
    return text;
  }

  /**
   * Validates structured proposals generated by AI without using eval or new Function.
   * Enforces that high-risk actions (delete, payments, external writes) CANNOT be autonomously executed.
   */
  public validateAIProposal(rawProposalJson: string | object): {
    valid: boolean;
    proposal?: AIActionProposalV2;
    error?: string;
  } {
    let parsed: any;
    try {
      if (typeof rawProposalJson === 'string') {
        parsed = JSON.parse(rawProposalJson);
      } else {
        parsed = rawProposalJson;
      }
    } catch {
      return { valid: false, error: 'Malformed JSON proposal from AI' };
    }

    if (!parsed || typeof parsed !== 'object') {
      return { valid: false, error: 'Proposal must be a structured object' };
    }

    const allowedActionTypes = ['create_note', 'update_property', 'append_text', 'schedule_task'];
    if (!allowedActionTypes.includes(parsed.actionType)) {
      return {
        valid: false,
        error: `Unauthorized proposal action type: "${parsed.actionType}". Destructive and financial operations cannot be proposed or executed by AI.`,
      };
    }

    const proposal: AIActionProposalV2 = {
      actionId: parsed.actionId || `prop_${Date.now()}`,
      actionType: parsed.actionType,
      targetResourceId: typeof parsed.targetResourceId === 'string' ? parsed.targetResourceId : undefined,
      expectedResourceVersion: typeof parsed.expectedResourceVersion === 'number' ? parsed.expectedResourceVersion : undefined,
      payload: parsed.payload && typeof parsed.payload === 'object' ? parsed.payload : {},
      rationale: typeof parsed.rationale === 'string' ? parsed.rationale : undefined,
      requiresUserConfirmation: true, // Always require user confirmation
    };

    return { valid: true, proposal };
  }

  /**
   * Validates if in-flight AI response should be accepted or discarded.
   * If vault was locked during streaming/completion, response is discarded immediately.
   */
  public processAICompletionResponse(
    scheduledSessionGeneration: number,
    responseContent: string
  ): { accepted: boolean; data?: string; error?: string } {
    const isValid = vaultLockSessionManagerV2.isAsyncOperationValid(scheduledSessionGeneration);
    if (!isValid) {
      return {
        accepted: false,
        error: 'AI response discarded: Vault was locked or session changed while request was in-flight.',
      };
    }

    return { accepted: true, data: responseContent };
  }
}

export const aiSecurityGuardV2 = AISecurityGuardV2.getInstance();
